{
  "world_id": "wld_cabin_signal",
  "name": "The Hollow Frequency",
  "description": "In a pine-choked ridge country where snow buries the roads for half the year, a lone radio host named Marlow Vance broadcasts a late-night call-in show from an isolated cabin station at the end of a forgotten forestry track. Her signal reaches almost no one, until she begins to receive transmissions from her own future: a voice that is unmistakably hers, calm, exhausted and afraid, warning her about what will happen in the cabin over the coming nights. The world is a closed pocket of horror and slow dread. The night never seems to end, the woods press against the windows, and every message from the future makes the next one harder to ignore and impossible to fully trust. The tone is claustrophobic and inevitable: the more Marlow tries to change what she hears, the more she suspects the broadcasts are not warnings but instructions.",
  "locations": [
    {
      "id": "loc_pinewatch_cabin",
      "name": "Pinewatch Cabin Station",
      "description": "A low timber cabin with a rusted tower antenna, a cramped broadcast booth lined with foam panels, a wood stove, a cellar full of old reel tapes, and a single window that always faces black trees. The nearest neighbor is forty miles of unplowed road away. The booth clock runs a few minutes ahead of every other clock in the building."
    }
  ],
  "factions": [
    {
      "id": "fac_night_listeners",
      "name": "The Night Listeners",
      "description": "A scattered group of insomniac callers who phone in every broadcast. Some are lonely, some are not entirely human voices, and all of them seem to know what Marlow will say before she says it.",
      "location_ids": ["loc_pinewatch_cabin"]
    },
    {
      "id": "fac_future_marlow",
      "name": "The Echo of Marlow",
      "description": "The unseen source of the future transmissions: one or more versions of Marlow Vance speaking from later nights, each more desperate and less consistent than the last.",
      "location_ids": ["loc_pinewatch_cabin"]
    }
  ],
  "rules": [
    {
      "id": "rul_future_signal",
      "statement": "Transmissions received on the cabin receiver originate from Marlow's own later broadcasts, and each one arrives a little earlier than the last.",
      "category": "technology"
    },
    {
      "id": "rul_no_dawn",
      "statement": "Inside the cabin's broadcast radius the night never lifts; clocks advance but the sky stays dark until the signal is silenced.",
      "category": "metaphysics"
    },
    {
      "id": "rul_fixed_events",
      "statement": "Events warned about in a transmission still occur, but never in the way Marlow expects; attempts to avoid them bend the outcome rather than prevent it.",
      "category": "metaphysics"
    },
    {
      "id": "rul_isolation",
      "statement": "No outside help can reach the cabin while the station is on air, because snow, dead phone lines, and failing vehicles cut it off.",
      "category": "physics"
    },
    {
      "id": "rul_listener_trust",
      "statement": "Callers treat the host's voice as authority, and a host who stops broadcasting is assumed by the town to have left or died.",
      "category": "social"
    }
  ],
  "history": [
    {
      "id": "evt_station_built",
      "name": "The Station Is Built",
      "description": "A forestry service builds the cabin and its antenna to relay weather and fire reports to the ridge, then abandons it after a winter when two operators stop answering their radios.",
      "era": "Decades before the broadcast",
      "location_ids": ["loc_pinewatch_cabin"]
    },
    {
      "id": "evt_marlow_arrives",
      "name": "Marlow Takes the Booth",
      "description": "Marlow Vance leases the abandoned cabin to start a late-night show, fleeing a failed city career and a silence she wants to fill with other people's voices.",
      "era": "Present year, autumn",
      "location_ids": ["loc_pinewatch_cabin"]
    },
    {
      "id": "evt_first_transmission",
      "name": "The First Warning",
      "description": "During a dead-air stretch, a voice identical to Marlow's breaks in with a short message: do not open the cellar. The recording does not appear on the station's logs.",
      "era": "Present year, first week",
      "location_ids": ["loc_pinewatch_cabin"]
    }
  ],
  "conflicts": [
    {
      "id": "cnf_warning_or_command",
      "name": "Warning or Command",
      "description": "Marlow must decide whether the Echo of Marlow is trying to save her or is steering her toward the fate it already endured, while the Night Listeners push her to keep broadcasting and the Echo begs her to go silent.",
      "faction_ids": ["fac_night_listeners", "fac_future_marlow"]
    }
  ]
}

